CREATE TABLE `article_service_relations` (`article_id` INT NOT NULL, `service_id` INT NOT NULL, PRIMARY KEY (`article_id`,`service_id`), CONSTRAINT `article_service_relations_article_id_fkey` FOREIGN KEY (`article_id`) REFERENCES `articles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `article_service_relations_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;